            data-testid="login-signup"
            onClick={handleSignup}
            style={{ flex: 1, padding: "10px", background: "#28a745", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer" }}
          >
            Sign Up
          </button>
        </div>
      </form>
    </div>
  );
}

