import { useState, useEffect } from "react";
import { useParams, Link } from "react-router";
import { useSocket, useSocketListener } from "wasp/client/webSocket";
import { useAuth } from "wasp/client/auth";

export function PollPage() {
  const { slug } = useParams<{ slug: string }>();
  const { socket, isConnected } = useSocket();
  const { data: user } = useAuth();

  const [pollState, setPollState] = useState<any>(null);
  const [pollError, setPollError] = useState<string | null>(null);
  const [isMissing, setIsMissing] = useState(false);

  // Reset page state on slug change
  useEffect(() => {
    setIsMissing(false);
    setPollState(null);
    setPollError(null);
  }, [slug]);

  // Handle subscribe / unsubscribe
  useEffect(() => {
    if (isConnected && socket && slug) {
      socket.emit("poll:subscribe", { slug });
      return () => {
        socket.emit("poll:unsubscribe", { slug });
      };
    }
  }, [slug, isConnected, socket]);

  // Listen for poll state updates
  useSocketListener("poll:state", (state: any) => {
    if (state.slug === slug) {
      setPollState(state);
      setPollError(null);
      setIsMissing(false);
    }
  });

  // Listen for poll errors
  useSocketListener("poll:error", (err: any) => {
    if (err.code === "POLL_NOT_FOUND") {
      setIsMissing(true);
    } else {
      setPollError(err.message);
    }
  });

  if (isMissing) {
    return (
      <div style={{ padding: "20px", textAlign: "center" }}>
        <h2 data-testid="poll-missing">Poll Not Found</h2>
        <p>The poll with slug "{slug}" does not exist.</p>
        <Link to="/">Go Home</Link>
      </div>
    );
  }

  if (!pollState) {
    return (
      <div style={{ padding: "20px", textAlign: "center" }}>
        <p>Loading poll details...</p>
      </div>
    );
  }

  const handleVote = (optionId: number) => {
    if (socket && slug) {
      socket.emit("poll:vote", { slug, optionId });
    }
  };

  const handleRetract = () => {
    if (socket && slug) {
      socket.emit("poll:retract", { slug });
    }
  };

  const handleClose = () => {
    if (socket && slug) {
      socket.emit("poll:close", { slug });
    }
  };

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
      <div style={{ marginBottom: "20px" }}>
        <Link to="/">← Back Home</Link>
      </div>

      <h1 data-testid="poll-question" style={{ marginBottom: "10px" }}>
        {pollState.question}
      </h1>

      <div style={{ display: "flex", gap: "15px", marginBottom: "20px", fontSize: "14px", color: "#666" }}>
        <div>
          Status: <strong data-testid="poll-status">{pollState.isClosed ? "closed" : "open"}</strong>
        </div>
        <div>
          Revision: <strong data-testid="poll-revision">{pollState.revision}</strong>
        </div>
        <div>
          Total Votes: <strong data-testid="poll-total-votes">{pollState.totalVotes}</strong>
        </div>
      </div>

      <div style={{ marginBottom: "20px", padding: "10px", background: "#f8f9fa", borderRadius: "4px" }}>
        <div>
          Leader Option ID: <strong data-testid="poll-leader">{pollState.leaderOptionId ?? "none"}</strong>
        </div>
        <div>
          My Vote Option ID: <strong data-testid="poll-my-vote">{pollState.myVoteOptionId ?? "none"}</strong>
        </div>
      </div>

      {pollError && (
        <div style={{ color: "red", padding: "10px", border: "1px solid red", borderRadius: "4px", marginBottom: "20px" }}>
          Error: {pollError}
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: "15px", marginBottom: "20px" }}>
        {pollState.options.map((opt: any) => {
          const isMyVote = pollState.myVoteOptionId === opt.id;
          return (
            <div
              key={opt.id}
              style={{
                padding: "15px",
                border: "1px solid #ddd",
                borderRadius: "4px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                background: isMyVote ? "#e9ecef" : "#fff",
              }}
            >
              <div>
                <div data-testid={`option-label-${opt.id}`} style={{ fontWeight: "bold", fontSize: "16px" }}>
                  {opt.label}
                </div>
                <div style={{ fontSize: "14px", color: "#666", marginTop: "5px" }}>
                  Votes: <span data-testid={`option-votes-${opt.id}`}>{opt.votes}</span>
                </div>
                {opt.voters.length > 0 && (
                  <div style={{ fontSize: "12px", color: "#888", marginTop: "3px" }}>
                    Voters: <span data-testid={`option-voters-${opt.id}`}>{opt.voters.join(",")}</span>
                  </div>
                )}
                {opt.voters.length === 0 && (
                  <span data-testid={`option-voters-${opt.id}`} style={{ display: "none" }}></span>
                )}
              </div>
              <button
                data-testid={`option-vote-${opt.id}`}
                onClick={() => handleVote(opt.id)}
                disabled={pollState.isClosed}
                style={{
                  padding: "8px 12px",
                  background: isMyVote ? "#28a745" : "#007bff",
                  color: "#fff",
                  border: "none",
                  borderRadius: "4px",
                  cursor: pollState.isClosed ? "not-allowed" : "pointer",
                  opacity: pollState.isClosed ? 0.6 : 1,
                }}
              >
                {isMyVote ? "Voted" : "Vote"}
              </button>
            </div>
          );
        })}
      </div>

      <div style={{ display: "flex", gap: "10px" }}>
        <button
          data-testid="poll-retract"
          onClick={handleRetract}
          disabled={pollState.isClosed || !pollState.myVoteOptionId}
          style={{
            padding: "10px 15px",
            background: "#dc3545",
            color: "#fff",
            border: "none",
            borderRadius: "4px",
            cursor: (pollState.isClosed || !pollState.myVoteOptionId) ? "not-allowed" : "pointer",
            opacity: (pollState.isClosed || !pollState.myVoteOptionId) ? 0.6 : 1,
          }}
        >
          Retract Vote
        </button>

        {!pollState.isClosed && (
          <button
            onClick={handleClose}
            style={{
              padding: "10px 15px",
              background: "#6c757d",
              color: "#fff",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            Close Poll
          </button>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { useAuth, logout } from "wasp/client/auth";
import { api } from "wasp/client/api";
import { useNavigate } from "react-router";
import { getUsername } from "wasp/auth";

export function MainPage() {
  const { data: user } = useAuth();
  const navigate = useNavigate();

  const [slug, setSlug] = useState("");
  const [question, setQuestion] = useState("");
  const [optionsText, setOptionsText] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [goSlug, setGoSlug] = useState("");

  const handleCreatePoll = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess("");

    const options = optionsText
      .split(",")
      .map((opt) => opt.trim())
      .filter((opt) => opt !== "");

    try {
      const response = await api.post("api/polls", {
        json: {
          slug,
          question,
          options,
        },
      });

      if (response.ok) {
        const data: any = await response.json();
        setSuccess(`Poll created successfully! Redirecting...`);
        setTimeout(() => {
          navigate(`/poll/${data.slug}`);
        }, 1500);
      } else {
        const errData: any = await response.json();
        setError(errData.error || "Failed to create poll.");
      }
    } catch (err: any) {
      if (err.response) {
        try {
          const errData = await err.response.json();
          setError(errData.error || "Failed to create poll.");
        } catch {
          setError("Failed to create poll.");
        }
      } else {
        setError(err.message || "An unexpected error occurred.");
      }
    }
  };

  const handleGoToPoll = (e: React.FormEvent) => {
    e.preventDefault();
    if (goSlug.trim()) {
      navigate(`/poll/${goSlug.trim()}`);
    }
  };

  const handleLogout = async () => {
    await logout();
    navigate("/login");
  };

  const username = user ? getUsername(user) : "";

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px", fontFamily: "sans-serif" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "30px" }}>
        <h2>PollRoom Dashboard</h2>
        {user && (
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <span>Welcome, <strong>{username}</strong>!</span>
            <button
              onClick={handleLogout}
              style={{ padding: "5px 10px", background: "#dc3545", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Log Out
            </button>
          </div>
        )}
      </div>

      <div style={{ display: "grid", gap: "30px" }}>
        {/* Create Poll Section */}
        <div style={{ padding: "20px", border: "1px solid #ccc", borderRadius: "8px", background: "#f8f9fa" }}>
          <h3>Create a New Poll</h3>
          <form onSubmit={handleCreatePoll}>
            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="poll-slug" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Slug</label>
              <input
                id="poll-slug"
                type="text"
                value={slug}
                onChange={(e) => setSlug(e.target.value)}
                placeholder="e.g. best-framework"
                style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
                required
              />
              <small style={{ color: "#666" }}>Only lowercase letters, numbers, and hyphens (1-32 chars).</small>
            </div>

            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="poll-question" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Question</label>
              <input
                id="poll-question"
                type="text"
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                placeholder="What is your favorite framework?"
                style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
                required
              />
            </div>

            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="poll-options" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Options (comma-separated)</label>
              <input
                id="poll-options"
                type="text"
                value={optionsText}
                onChange={(e) => setOptionsText(e.target.value)}
                placeholder="Wasp, Next.js, Remix, SvelteKit"
                style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
                required
              />
              <small style={{ color: "#666" }}>Enter 2 to 8 unique options separated by commas.</small>
            </div>

            {error && <div style={{ color: "red", marginBottom: "15px" }}>Error: {error}</div>}
            {success && <div style={{ color: "green", marginBottom: "15px" }}>{success}</div>}

            <button
              type="submit"
              style={{ width: "100%", padding: "10px", background: "#28a745", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer", fontWeight: "bold" }}
            >
              Create Poll
            </button>
          </form>
        </div>

        {/* Go to Poll Section */}
        <div style={{ padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
          <h3>Go to Existing Poll</h3>
          <form onSubmit={handleGoToPoll} style={{ display: "flex", gap: "10px" }}>
            <input
              type="text"
              value={goSlug}
              onChange={(e) => setGoSlug(e.target.value)}
              placeholder="Enter poll slug"
              style={{ flex: 1, padding: "8px", boxSizing: "border-box" }}
              required
            />
            <button
              type="submit"
              style={{ padding: "8px 15px", background: "#007bff", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Go
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

