import { type CreatePoll, type GetPollResults } from "wasp/server/api";

export const createPoll: CreatePoll = async (req, res, context) => {
  // 1. 401 Unauthenticated
  if (!context.user) {
    return res.status(401).json({ error: "UNAUTHENTICATED" });
  }

  const { slug, question, options } = req.body;

  // 2. 400 Invalid Payload
  if (typeof slug !== "string" || !/^[a-z0-9-]{1,32}$/.test(slug)) {
    return res.status(400).json({ error: "INVALID_PAYLOAD" });
  }

  if (typeof question !== "string" || question.trim() === "") {
    return res.status(400).json({ error: "INVALID_PAYLOAD" });
  }

  if (
    !Array.isArray(options) ||
    options.length < 2 ||
    options.length > 8 ||
    options.some((opt) => typeof opt !== "string" || opt.trim() === "")
  ) {
    return res.status(400).json({ error: "INVALID_PAYLOAD" });
  }

  const uniqueOptions = new Set(options);
  if (uniqueOptions.size !== options.length) {
    return res.status(400).json({ error: "INVALID_PAYLOAD" });
  }

  // 3. 409 Slug Taken
  const existingPoll = await context.entities.Poll.findUnique({
    where: { slug },
  });
  if (existingPoll) {
    return res.status(409).json({ error: "SLUG_TAKEN" });
  }

  const username = context.user.identities.username?.id;
  if (!username) {
    return res.status(401).json({ error: "UNAUTHENTICATED" });
  }

  const createdPoll = await context.entities.Poll.create({
    data: {
      slug,
      question,
      isClosed: false,
      revision: 0,
      creatorId: context.user.id,
      options: {
        create: options.map((label, index) => ({
          label,
          position: index,
        })),
      },
    },
    include: {
      options: {
        orderBy: {
          position: "asc",
        },
      },
    },
  });

  return res.status(201).json({
    slug: createdPoll.slug,
    question: createdPoll.question,
    isClosed: createdPoll.isClosed,
    revision: createdPoll.revision,
    creator: username,
    options: createdPoll.options.map((opt) => ({
      id: opt.id,
      label: opt.label,
      position: opt.position,
    })),
  });
};

export const getPollResults: GetPollResults = async (req, res, context) => {
  const slug = req.params.slug as string;

  const poll: any = await context.entities.Poll.findUnique({
    where: { slug },
    include: {
      options: {
        orderBy: {
          position: "asc",
        },
        include: {
          votes: {
            include: {
              user: {
                include: {
                  auth: {
                    include: {
                      identities: true,
                    },
                  },
                },
              },
            },
          },
        },
      },
    },
  });

  if (!poll) {
    return res.status(404).json({ error: "POLL_NOT_FOUND" });
  }

  let totalVotes = 0;
  const optionResults = poll.options.map((opt: any) => {
    const votesCount = opt.votes.length;
    totalVotes += votesCount;

    const voters = opt.votes
      .map((v: any) => v.user?.auth?.identities?.find((id: any) => id.providerName === "username")?.providerUserId)
      .filter((u: any): u is string => typeof u === "string" && u !== "")
      .sort();

    return {
      id: opt.id,
      label: opt.label,
      position: opt.position,
      votes: votesCount,
      voters,
    };
  });

  let leaderOptionId: number | null = null;
  if (totalVotes > 0) {
    let maxVotes = -1;
    let bestPosition = Infinity;
    for (const optRes of optionResults) {
      if (optRes.votes > maxVotes) {
        maxVotes = optRes.votes;
        leaderOptionId = optRes.id;
        bestPosition = optRes.position;
      } else if (optRes.votes === maxVotes) {
        if (optRes.position < bestPosition) {
          leaderOptionId = optRes.id;
          bestPosition = optRes.position;
        }
      }
    }
  }

  return res.status(200).json({
    slug: poll.slug,
    question: poll.question,
    isClosed: poll.isClosed,
    revision: poll.revision,
    totalVotes,
    leaderOptionId,
    options: optionResults,
  });
};

import { useState } from "react";
import { useAuth, logout } from "wasp/client/auth";
import { api } from "wasp/client/api";
import { useNavigate } from "react-router";

export function MainPage() {
  const { data: user } = useAuth();
  const navigate = useNavigate();

  const [slug, setSlug] = useState("");
  const [question, setQuestion] = useState("");
  const [optionsText, setOptionsText] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [goSlug, setGoSlug] = useState("");

  const handleCreatePoll = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess("");

    const options = optionsText
      .split(",")
      .map((opt) => opt.trim())
      .filter((opt) => opt !== "");

    try {
      const response = await api.post("api/polls", {
        json: {
          slug,
          question,
          options,
        },
      });

      if (response.ok) {
        const data: any = await response.json();
        setSuccess(`Poll created successfully! Redirecting...`);
        setTimeout(() => {
          navigate(`/poll/${data.slug}`);
        }, 1500);
      } else {
        const errData: any = await response.json();
        setError(errData.error || "Failed to create poll.");
      }
    } catch (err: any) {
      if (err.response) {
        try {
          const errData = await err.response.json();
          setError(errData.error || "Failed to create poll.");
        } catch {
          setError("Failed to create poll.");
        }
      } else {
        setError(err.message || "An unexpected error occurred.");
      }
    }
  };

  const handleGoToPoll = (e: React.FormEvent) => {
    e.preventDefault();
    if (goSlug.trim()) {
      navigate(`/poll/${goSlug.trim()}`);
    }
  };

  const handleLogout = async () => {
    await logout();
    navigate("/login");
  };

  const username = user?.identities?.username?.id || "";

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px", fontFamily: "sans-serif" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "30px" }}>
        <h2>PollRoom Dashboard</h2>
        {user && (
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <span>Welcome, <strong>{username}</strong>!</span>
            <button
              onClick={handleLogout}
              style={{ padding: "5px 10px", background: "#dc3545", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Log Out
            </button>
          </div>
        )}
      </div>

      <div style={{ display: "grid", gap: "30px" }}>
        {/* Create Poll Section */}
        <div style={{ padding: "20px", border: "1px solid #ccc", borderRadius: "8px", background: "#f8f9fa" }}>
          <h3>Create a New Poll</h3>
          <form onSubmit={handleCreatePoll}>
            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="poll-slug" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Slug</label>
              <input
                id="poll-slug"
                type="text"
                value={slug}
                onChange={(e) => setSlug(e.target.value)}
                placeholder="e.g. best-framework"
                style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
                required
              />
              <small style={{ color: "#666" }}>Only lowercase letters, numbers, and hyphens (1-32 chars).</small>
            </div>

            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="poll-question" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Question</label>
              <input
                id="poll-question"
                type="text"
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                placeholder="What is your favorite framework?"
                style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
                required
              />
            </div>

            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="poll-options" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Options (comma-separated)</label>
              <input
                id="poll-options"
                type="text"
                value={optionsText}
                onChange={(e) => setOptionsText(e.target.value)}
                placeholder="Wasp, Next.js, Remix, SvelteKit"
                style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
                required
              />
              <small style={{ color: "#666" }}>Enter 2 to 8 unique options separated by commas.</small>
            </div>

            {error && <div style={{ color: "red", marginBottom: "15px" }}>Error: {error}</div>}
            {success && <div style={{ color: "green", marginBottom: "15px" }}>{success}</div>}

            <button
              type="submit"
              style={{ width: "100%", padding: "10px", background: "#28a745", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer", fontWeight: "bold" }}
            >
              Create Poll
            </button>
          </form>
        </div>

        {/* Go to Poll Section */}
        <div style={{ padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
          <h3>Go to Existing Poll</h3>
          <form onSubmit={handleGoToPoll} style={{ display: "flex", gap: "10px" }}>
            <input
              type="text"
              value={goSlug}
              onChange={(e) => setGoSlug(e.target.value)}
              placeholder="Enter poll slug"
              style={{ flex: 1, padding: "8px", boxSizing: "border-box" }}
              required
            />
            <button
              type="submit"
              style={{ padding: "8px 15px", background: "#007bff", color: "#fff", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Go
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

import { type WebSocketDefinition } from "wasp/server/webSocket";
import { prisma } from "wasp/server";

export const webSocketFn: WebSocketDefinition = (io, context) => {
  io.on("connection", (socket) => {
    // Helper to send errors
    const sendError = (code: string, message: string) => {
      socket.emit("poll:error", { code, message });
    };

    // helper to send personalized state to a socket
    const sendPersonalizedState = async (sock: any, slug: string) => {
      const poll: any = await context.entities.Poll.findUnique({
        where: { slug },
        include: {
          options: {
            orderBy: {
              position: "asc",
            },
            include: {
              votes: {
                include: {
                  user: {
                    include: {
                      auth: {
                        include: {
                          identities: true,
                        },
                      },
                    },
                  },
                },
              },
            },
          },
        },
      });

      if (!poll) return;

      const userId = sock.data.user?.id;
      let totalVotes = 0;
      let myVoteOptionId: number | null = null;

      const optionResults = poll.options.map((opt: any) => {
        const votesCount = opt.votes.length;
        totalVotes += votesCount;

        const hasMyVote = opt.votes.some((v: any) => v.userId === userId);
        if (hasMyVote) {
          myVoteOptionId = opt.id;
        }

        const voters = opt.votes
          .map((v: any) => v.user?.auth?.identities?.find((id: any) => id.providerName === "username")?.providerUserId)
          .filter((u: any): u is string => typeof u === "string" && u !== "")
          .sort();

        return {
          id: opt.id,
          label: opt.label,
          position: opt.position,
          votes: votesCount,
          voters,
        };
      });

      let leaderOptionId: number | null = null;
      if (totalVotes > 0) {
        let maxVotes = -1;
        let bestPosition = Infinity;
        for (const optRes of optionResults) {
          if (optRes.votes > maxVotes) {
            maxVotes = optRes.votes;
            leaderOptionId = optRes.id;
            bestPosition = optRes.position;
          } else if (optRes.votes === maxVotes) {
            if (optRes.position < bestPosition) {
              leaderOptionId = optRes.id;
              bestPosition = optRes.position;
            }
          }
        }
      }

      sock.emit("poll:state", {
        slug: poll.slug,
        question: poll.question,
        isClosed: poll.isClosed,
        revision: poll.revision,
        totalVotes,
        leaderOptionId,
        myVoteOptionId,
        options: optionResults,
      });
    };

    // helper to broadcast personalized state to all subscribers of a poll
    const broadcastState = async (slug: string) => {
      const sockets = await io.in(slug).fetchSockets();
      await Promise.all(sockets.map((s) => sendPersonalizedState(s, slug)));
    };

    // 1. poll:subscribe
    socket.on("poll:subscribe", async (payload: any) => {
      if (!socket.data.user) {
        return sendError("UNAUTHENTICATED", "You must be authenticated to perform this action.");
      }

      if (!payload || typeof payload !== "object" || typeof payload.slug !== "string" || payload.slug === "") {
        return sendError("INVALID_PAYLOAD", "Invalid subscribe payload.");
      }

      const poll = await context.entities.Poll.findUnique({
        where: { slug: payload.slug },
      });

      if (!poll) {
        return sendError("POLL_NOT_FOUND", "The requested poll was not found.");
      }

      socket.join(payload.slug);
      await sendPersonalizedState(socket, payload.slug);
    });

    // 2. poll:unsubscribe
    socket.on("poll:unsubscribe", async (payload: any) => {
      if (!socket.data.user) {
        return sendError("UNAUTHENTICATED", "You must be authenticated to perform this action.");
      }

      if (!payload || typeof payload !== "object" || typeof payload.slug !== "string" || payload.slug === "") {
        return sendError("INVALID_PAYLOAD", "Invalid unsubscribe payload.");
      }

      const poll = await context.entities.Poll.findUnique({
        where: { slug: payload.slug },
      });

      if (!poll) {
        return sendError("POLL_NOT_FOUND", "The requested poll was not found.");
      }

      socket.leave(payload.slug);
    });

    // 3. poll:vote
    socket.on("poll:vote", async (payload: any) => {
      if (!socket.data.user) {
        return sendError("UNAUTHENTICATED", "You must be authenticated to perform this action.");
      }

      if (
        !payload ||
        typeof payload !== "object" ||
        typeof payload.slug !== "string" ||
        payload.slug === "" ||
        typeof payload.optionId !== "number" ||
        !Number.isInteger(payload.optionId)
      ) {
        return sendError("INVALID_PAYLOAD", "Invalid vote payload.");
      }

      const { slug, optionId } = payload;

      const poll = await context.entities.Poll.findUnique({
        where: { slug },
        include: {
          options: true,
        },
      });

      if (!poll) {
        return sendError("POLL_NOT_FOUND", "The requested poll was not found.");
      }

      // Check if socket is subscribed (i.e. in the room)
      if (!socket.rooms.has(slug)) {
        return sendError("NOT_SUBSCRIBED", "You are not subscribed to this poll.");
      }

      if (poll.isClosed) {
        return sendError("POLL_CLOSED", "This poll is closed.");
      }

      const optionExists = poll.options.some((o) => o.id === optionId);
      if (!optionExists) {
        return sendError("OPTION_NOT_FOUND", "The selected option does not exist in this poll.");
      }

      // Check existing vote
      const existingVote = await context.entities.Vote.findUnique({
        where: {
          pollId_userId: {
            pollId: poll.id,
            userId: socket.data.user.id,
          },
        },
      });

      if (existingVote) {
        if (existingVote.optionId === optionId) {
          // No-op
          return await sendPersonalizedState(socket, slug);
        } else {
          // Change vote
          await prisma.$transaction([
            prisma.vote.update({
              where: { id: existingVote.id },
              data: { optionId },
            }),
            prisma.poll.update({
              where: { id: poll.id },
              data: { revision: { increment: 1 } },
            }),
          ]);
        }
      } else {
        // New vote
        await prisma.$transaction([
          prisma.vote.create({
            data: {
              pollId: poll.id,
              optionId,
              userId: socket.data.user.id,
            },
          }),
          prisma.poll.update({
            where: { id: poll.id },
            data: { revision: { increment: 1 } },
          }),
        ]);
      }

      await broadcastState(slug);
    });

    // 4. poll:retract
    socket.on("poll:retract", async (payload: any) => {
      if (!socket.data.user) {
        return sendError("UNAUTHENTICATED", "You must be authenticated to perform this action.");
      }

      if (!payload || typeof payload !== "object" || typeof payload.slug !== "string" || payload.slug === "") {
        return sendError("INVALID_PAYLOAD", "Invalid retract payload.");
      }

      const { slug } = payload;

      const poll = await context.entities.Poll.findUnique({
        where: { slug },
      });

      if (!poll) {
        return sendError("POLL_NOT_FOUND", "The requested poll was not found.");
      }

      if (!socket.rooms.has(slug)) {
        return sendError("NOT_SUBSCRIBED", "You are not subscribed to this poll.");
      }

      if (poll.isClosed) {
        return sendError("POLL_CLOSED", "This poll is closed.");
      }

      const existingVote = await context.entities.Vote.findUnique({
        where: {
          pollId_userId: {
            pollId: poll.id,
            userId: socket.data.user.id,
          },
        },
      });

      if (!existingVote) {
        return sendError("NO_ACTIVE_VOTE", "You have not voted in this poll.");
      }

      await prisma.$transaction([
        prisma.vote.delete({
          where: { id: existingVote.id },
        }),
        prisma.poll.update({
          where: { id: poll.id },
          data: { revision: { increment: 1 } },
        }),
      ]);

      await broadcastState(slug);
    });

    // 5. poll:close
    socket.on("poll:close", async (payload: any) => {
      if (!socket.data.user) {
        return sendError("UNAUTHENTICATED", "You must be authenticated to perform this action.");
      }

      if (!payload || typeof payload !== "object" || typeof payload.slug !== "string" || payload.slug === "") {
        return sendError("INVALID_PAYLOAD", "Invalid close payload.");
      }

      const { slug } = payload;

      const poll = await context.entities.Poll.findUnique({
        where: { slug },
      });

      if (!poll) {
        return sendError("POLL_NOT_FOUND", "The requested poll was not found.");
      }

      if (!socket.rooms.has(slug)) {
        return sendError("NOT_SUBSCRIBED", "You are not subscribed to this poll.");
      }

      if (poll.creatorId !== socket.data.user.id) {
        return sendError("NOT_POLL_CREATOR", "Only the poll creator can close it.");
      }

      if (poll.isClosed) {
        return sendError("ALREADY_CLOSED", "The poll is already closed.");
      }

      await prisma.$transaction([
        prisma.poll.update({
          where: { id: poll.id },
          data: {
            isClosed: true,
            revision: { increment: 1 },
          },
        }),
      ]);

      await broadcastState(slug);
    });
  });
};
